package com.shortlinkx.config;
import jakarta.servlet.http.*;import org.springframework.context.annotation.*;import org.springframework.web.servlet.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
@Configuration public class WebConfig implements WebMvcConfigurer{@Bean RateLimitInterceptor rateLimitInterceptor(){return new RateLimitInterceptor();}@Override public void addInterceptors(InterceptorRegistry r){r.addInterceptor(rateLimitInterceptor()).addPathPatterns("/api/**");}static class RateLimitInterceptor implements HandlerInterceptor{private static final int MAX=60;private static final long WINDOW=60000;private final Map<String,Window> map=new ConcurrentHashMap<>();public boolean preHandle(HttpServletRequest q,HttpServletResponse s,Object h){String ip=q.getRemoteAddr();long now=System.currentTimeMillis();Window w=map.compute(ip,(k,o)->o==null||now-o.start>WINDOW?new Window(now,1):new Window(o.start,o.count+1));if(w.count>MAX){s.setStatus(429);s.setHeader("Retry-After","60");return false;}return true;}record Window(long start,int count){}}}
